OPTIONAL MATCH (bp:BiologicalProcess {commonName: "Increased Platelet Production"})

// Drugs -> Genes -> BiologicalProcess (chemical effects or binding)
OPTIONAL MATCH (d1:Drug)-[r1:CHEMICALINCREASESEXPRESSION|CHEMICALDECREASESEXPRESSION|CHEMICALBINDSGENE]->(g:Gene)-[r2:GENEPARTICIPATESINBIOLOGICALPROCESS]->(bp)

// Drugs -> Disease (in case 'Increased Platelet Production' is modeled as a Disease)
OPTIONAL MATCH (d2:Drug)-[r3:DRUGTREATSDISEASE|DRUGCAUSESEFFECT]->(dis:Disease {commonName: "Increased Platelet Production"})

// Explicitly check the drug Eltrombopag for the same patterns
OPTIONAL MATCH (e:Drug {commonName: "Eltrombopag"})-[er1:CHEMICALINCREASESEXPRESSION|CHEMICALDECREASESEXPRESSION|CHEMICALBINDSGENE]->(eg:Gene)-[er2:GENEPARTICIPATESINBIOLOGICALPROCESS]->(bp)
OPTIONAL MATCH (e)-[er3:DRUGTREATSDISEASE|DRUGCAUSESEFFECT]->(dis2:Disease {commonName: "Increased Platelet Production"})

RETURN bp, d1, r1, g, r2, d2, r3, dis, e, er1, eg, er2, er3, dis2
